        try {
          const data = formValues(addForm);
          await apiFetch("/api/todos", { method: "POST", body: data });
          addForm.reset();
          loadTodos();
        } catch (err) {
          if (err instanceof ApiError) showMessage(err.message, "error");
          else showMessage("Failed to add todo.", "error");
        }
      });
    });

    prevBtn.addEventListener("click", () => {
      currentOffset = Math.max(0, currentOffset - LIMIT);
      loadTodos();
    });

    nextBtn.addEventListener("click", () => {
      currentOffset += LIMIT;
      loadTodos();
    });

    for (const radio of filterRadios) {
      radio.addEventListener("change", () => {
        currentFilter = radio.value;
        currentOffset = 0;
        loadTodos();
      });
    }

    signoutBtn.addEventListener("click", () => {
      clearToken();
      location.href = "login.html";
    });

    await loadUser();
    await loadTodos();
  </script>
</body>
</html>
